layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(226, 232, 240); border-left: 4px solid rgb(148, 163, 184); border-radius: 0px; font-family: ui-serif, Georgia, Cambria, "times new roman", Times, serif; font-size: 18px; font-weight: 400; font-style: italic; line-height: 1.556; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 2px solid var(--ryt-border); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: 0.48px; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(38, 38, 38); background-color: rgb(244, 244, 245); border-bottom: 2px solid rgb(212, 212, 216); border-radius: 4px 4px 0px 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(38, 38, 38); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2px; padding-right: 4px; padding-bottom: 2px; padding-left: 4px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(17, 24, 39); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.429; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(17, 24, 39); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.333; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-bottom: 2px solid var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: rgb(82, 82, 91); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 400; font-style: normal; line-height: 1.333; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(82, 82, 91); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(82, 82, 91); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.556; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(82, 82, 91); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), text-decoration-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), fill 0.15s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.15s cubic-bezier(0.4, 0, 0.2, 1), -webkit-text-decoration-color 0.15s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: rgb(17 24 39/1); border-bottom-width: 2px; border-bottom-width: 0px }
[data-ryt="brand"]:hover { color: rgb(17 24 39/1); border-bottom-width: 2px; border-bottom-width: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(17 24 39/1); border-bottom-width: 2px; color: rgb(115 115 115/1) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { background-color: rgb(228 228 231/1) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(17 24 39/1); border-bottom-width: 2px }
article[data-ryt="rec-card"]:hover { color: rgb(17 24 39/1); border-bottom-width: 2px; color: rgb(115 115 115/1) }
